import json
_FIELDS = ("payload", "done", "token", "until", "attempts", "dead")
def _int(value):
    return isinstance(value, int) and not isinstance(value, bool)
class Queue:
    def __init__(self, max_attempts=3):
        if not _int(max_attempts) or max_attempts <= 0: raise ValueError("max_attempts must be a positive integer")
        self.items = {}; self.serial = 0; self.max_attempts = max_attempts; self.seen = {}
    def enqueue(self, key, payload):
        if key not in self.items:
            self.items[key] = {"payload": payload, "done": False, "token": None, "until": None, "attempts": 0, "dead": False}
    def claim(self, key, now=0, ttl=10):
        if not _int(now) or now < 0: raise ValueError("now must be an integer >= 0")
        if not _int(ttl) or ttl <= 0: raise ValueError("ttl must be a positive integer")
        row = self.items.get(key)
        if row is None or row["done"] or row["dead"]: return None
        if row["token"] is not None:
            if now < row["until"]: return None
            row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts:
            row["dead"] = True; return None
        self.serial += 1; row["token"] = self.serial; row["until"] = now + ttl; row["attempts"] += 1
        return row["payload"], self.serial
    def ack(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["token"] is None or row["token"] != token: return False
        row["done"] = True; return True
    def retry(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["dead"] or row["token"] is None or row["token"] != token: return False
        row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts: row["dead"] = True
        return True
    def dumps(self):
        return json.dumps({"version": 2, "serial": self.serial, "max_attempts": self.max_attempts,
                           "items": {k: {f: row[f] for f in _FIELDS} for k, row in self.items.items()},
                           "seen": self.seen})
    @classmethod
    def loads(cls, text):
        try: data = json.loads(text)
        except (TypeError, ValueError) as exc: raise ValueError("malformed JSON") from exc
        if not isinstance(data, dict) or data.get("version") != 2 or isinstance(data.get("version"), bool):
            raise ValueError("unsupported snapshot")
        for f in ("serial", "max_attempts", "items", "seen"):
            if f not in data: raise ValueError("missing field " + f)
        if not _int(data["serial"]) or data["serial"] < 0: raise ValueError("bad serial")
        if not isinstance(data["items"], dict) or not isinstance(data["seen"], dict): raise ValueError("bad snapshot")
        q = cls(data["max_attempts"]); q.serial = data["serial"]; q.seen = dict(data["seen"])
        for key, row in data["items"].items():
            if not isinstance(row, dict) or any(f not in row for f in _FIELDS): raise ValueError("bad item " + key)
            if not _int(row["attempts"]) or row["attempts"] < 0: raise ValueError("bad attempts")
            if row["token"] is not None and (not _int(row["token"]) or row["token"] > q.serial): raise ValueError("bad token")
            if row["token"] is not None and not _int(row["until"]): raise ValueError("bad until")
            q.items[key] = {f: row[f] for f in _FIELDS}
        return q
